import { groupBy } from 'lodash';

const groupLogsByType = (
  rawLogs: T.BuildLog[],
  filterType: FilterState,
): FilteredLog[] => {
  const logs = rawLogs.map((l, index) => ({ ...l, index }));
  if (filterType === 'all' || logs.length === 0) {
    return [{ hidden: false, logs }];
  }

  const { errors, warnings, others } = groupBy(logs, (log) => {
    if (log.error) return 'errors';
    if (log.warning) return 'warnings';
    return 'others';
  });

  const groupedLogs = [
    { hidden: filterType !== 'errors', logs: errors },
    { hidden: filterType !== 'warnings', logs: warnings },
    { hidden: true, logs: others },
  ];

  return groupedLogs.filter((group) => group.hidden || filterType === group.logs[0].type);
};
```

