let velocity = 0;

// Main simulation loop
function update() {
  // Update the pendulum's velocity using Euler's method
  velocity += (gravity * Math.sin(angle) - pendulumLength * (velocity / pendulumPeriod) * Math.cos(angle)) * deltaTime;
  angle += velocity * deltaTime;

  // Draw the pendulum
